var background_RulesGroup;
(function (RulesGroup) {
    RulesGroup[RulesGroup["Regular"] = 0] = "Regular";
    RulesGroup[RulesGroup["RemoveParam"] = 1] = "RemoveParam";
    RulesGroup[RulesGroup["RemoveHeader"] = 2] = "RemoveHeader";
    RulesGroup[RulesGroup["Csp"] = 3] = "Csp";
    RulesGroup[RulesGroup["BadFilter"] = 4] = "BadFilter";
})(background_RulesGroup || (background_RulesGroup = {}));
/**
 * Contains logic on how to divide the rules into certain groups.
 *
 * @see {@link RulesGroup}
 */
class background_DeclarativeRulesGrouper {
    /**
     * Returns group of the indexed rule.
     *
     * @param indexedNetworkRuleWithHash Indexed network rule with hash.
     *
     * @returns Group of the indexed rule.
     */
    static getRuleGroup(indexedNetworkRuleWithHash) {
        const { rule } = indexedNetworkRuleWithHash;
        if (rule.isOptionEnabled(background_NetworkRuleOption.RemoveParam)) {
            return background_RulesGroup.RemoveParam;
        }
        if (rule.isOptionEnabled(background_NetworkRuleOption.RemoveHeader)) {
            return background_RulesGroup.RemoveHeader;
        }
        if (rule.isOptionEnabled(background_NetworkRuleOption.Csp)) {
            return background_RulesGroup.Csp;
        }
        if (rule.isOptionEnabled(background_NetworkRuleOption.Badfilter)) {
            return background_RulesGroup.BadFilter;
        }
        return background_RulesGroup.Regular;
    }
    /**
     * Splits the list of indexed rules into an index with groups.
     *
     * @param rules List of indexed rules.
     *
     * @returns Index with grouped, indexed rules.
     */
    static splitRulesByGroups(rules) {
        const rulesToProcess = {
            [background_RulesGroup.RemoveParam]: [],
            [background_RulesGroup.RemoveHeader]: [],
            [background_RulesGroup.BadFilter]: [],
            [background_RulesGroup.Regular]: [],
            [background_RulesGroup.Csp]: [],
        };
        // Categorizing rule groups
        rules.forEach((indexedNetworkRuleWithHash) => {
            const group = background_DeclarativeRulesGrouper.getRuleGroup(indexedNetworkRuleWithHash);
            rulesToProcess[group].push(indexedNetworkRuleWithHash);
        });
        return rulesToProcess;
    }
}

