        const { scriptTexts, scriptletDataList, } = background_CosmeticApi.getScriptsAndScriptletsData(cosmeticResult);
        const { configuration } = background_index_mv3_appContext;
        const areHitsStatsCollected = configuration?.settings.collectStats || false;
        const cssText = background_CosmeticApi.getCssText(cosmeticResult, areHitsStatsCollected);
