/**
 * Injects cosmetic rules into tabs, opened before app initialization.
 */
class background_TabsCosmeticInjector {
    /**
     * Creates contexts for tabs opened before api initialization and
     * applies cosmetic rules for each frame.
     */
    static async processOpenTabs() {
        const currentTabs = await background_browser_polyfill.tabs.query({});
        const tasks = currentTabs.map((tab) => background_TabsCosmeticInjector.processOpenTab(tab));
        const promises = await Promise.allSettled(tasks);
        // Handles errors
        promises.forEach((promise) => {
            if (promise.status === 'rejected') {
                background_common_logger_logger.error('[tswebextension.processOpenTabs]: cannot inject cosmetic to open tab: ', promise.reason);
            }
        });
        background_index_mv3_appContext.cosmeticsInjectedOnStartup = true;
    }
    /**
     * Creates context for tab opened before api initialization and
     * applies cosmetic rules for each frame.
     *
     * @param tab Tab details.
     */
    static async processOpenTab(tab) {
        if (!background_TabContext.isBrowserTab(tab)) {
            return;
        }
        const tabContext = new background_TabContext(tab);
        const tabId = tab.id;
        background_tabsApi.context.set(tabId, tabContext);
        background_tabsApi.updateTabMainFrameRule(tabId);
        const frames = await chrome.webNavigation.getAllFrames({ tabId });
        if (!frames) {
            return;
        }
        const currentTime = Date.now();
        frames.forEach((frameDetails) => {
            const { url, frameId, parentFrameId, parentDocumentId, documentId, } = frameDetails;
            background_tabsApi.setFrameContext(tabId, frameId, new background_FrameMV3({
                tabId,
                frameId,
                parentFrameId,
                url,
                timeStamp: currentTime,
                parentDocumentId,
                documentId,
            }));
            background_CosmeticFrameProcessor.handleFrame({
                tabId,
                frameId,
                parentFrameId,
                url,
                timeStamp: currentTime,
                parentDocumentId,
                documentId,
            });
            // TODO: Instead of this, it’s better to use the runtime.onStartup and runtime.onInstalled
            // events to inject cosmetics once during the extension's initialization
            // and browser startup without flags.
            // However, this would require big refactoring of the extension.
            /**
             * This condition prevents applying cosmetic rules to the tab multiple times.
             * Applying them once after the extension's initialization is enough.
             */
            if (background_index_mv3_appContext.cosmeticsInjectedOnStartup) {
                return;
            }
            // TODO: Can be moved to CosmeticApi.injectCosmetic() like in MV2
            // since it is used not only here.
            // Note: this is an async function, but we will not await it because
            // events do not support async listeners.
            Promise.all([
                background_CosmeticApi.applyJsFuncsByTabAndFrame(tabId, frameId),
                background_CosmeticApi.applyCssByTabAndFrame(tabId, frameId),
                background_CosmeticApi.applyScriptletsByTabAndFrame(tabId, frameId),
            ]).catch((e) => background_common_logger_logger.error(e));
            const frameContext = background_tabsApi.getFrameContext(tabId, frameId);
            if (!frameContext?.cosmeticResult) {
                // eslint-disable-next-line max-len
                background_common_logger_logger.debug(`[tswebextension.processOpenTab]: cannot log script rules due to not having cosmetic result for tabId: ${tabId}, frameId: ${frameId}.`);
                return;
            }
            const isMainFrame = frameId === background_MAIN_FRAME_ID;
            background_CosmeticApi.logScriptRules({
                url,
                tabId,
                cosmeticResult: frameContext.cosmeticResult,
                timestamp: currentTime,
                contentType: isMainFrame ? background_ContentType.Document : background_ContentType.Subdocument,
            });
        });
    }
}

