        background_RequestEvents.onBeforeSendHeaders.init(background_browser_polyfill.webRequest.onBeforeSendHeaders, background_RequestEvents.handleOnBeforeSendHeaders, { urls: ['<all_urls>'] }, onBeforeSendHeadersOptions);
        const onResponseStartedOptions = ['responseHeaders', 'extraHeaders'];
        background_RequestEvents.onResponseStarted.init(background_browser_polyfill.webRequest.onResponseStarted, background_RequestEvents.handleOnResponseStarted, { urls: ['<all_urls>'] }, onResponseStartedOptions);
        const onHeadersReceivedOptions = ['responseHeaders'];
        const onHeadersReceivedOptionTypes = background_browser_polyfill.webRequest.OnHeadersReceivedOptions;
        if (typeof onHeadersReceivedOptionTypes !== 'undefined'
            && Object.prototype.hasOwnProperty.call(onBeforeSendHeadersOptionTypes, 'EXTRA_HEADERS')) {
            onHeadersReceivedOptions.push('extraHeaders');
        }
        background_RequestEvents.onHeadersReceived.init(background_browser_polyfill.webRequest.onHeadersReceived, background_RequestEvents.handleOnHeadersReceived, { urls: ['<all_urls>'] }, onHeadersReceivedOptions);
        background_RequestEvents.onCompleted.init(background_browser_polyfill.webRequest.onCompleted, background_RequestEvents.handleOnCompleted, { urls: ['<all_urls>'] }, ['responseHeaders']);
        background_RequestEvents.onErrorOccurred.init(background_browser_polyfill.webRequest.onErrorOccurred, background_RequestEvents.handleOnErrorOccurred, { urls: ['<all_urls>'] });
